/* WF-W11-02-01/02, W11.2. No real attendance, QR, meeting or student writes. */
const ATT_LABELS={online:['Online anwesend','Present online'],presence:['In Präsenz anwesend','Present in person'],excused:['Entschuldigt abwesend','Excused absence'],unexcused:['Unentschuldigt abwesend','Unexcused absence']};
const ATTENDANCE={selected:'UNIT-01',error:null,errorRoute:'',records:[
 {id:'UNIT-01',group:'T-01',subject:['Mathematik','Mathematics'],date:'2026-11-02',time:'09:00–09:45',status:'unexcused',reportDraft:'',reviewDraft:'',proposed:'online',checked:false,request:null,history:[]},
 {id:'UNIT-02',group:'D-B1-02',subject:['Deutsch','German'],date:'2026-11-02',time:'11:00–11:45',status:'online',reportDraft:'',reviewDraft:'',proposed:'online',checked:false,request:null,history:[]}
]};
function attendanceRecord(){return ATTENDANCE.records.find(r=>r.id===ATTENDANCE.selected)}
function attendanceOwnRoute(){return route().split('?')[0]==='/portal/student/attendance'}
function attendanceTeacherRoute(){return route().split('?')[0]==='/portal/teacher/attendance'}
function attendanceCounts(){const counts={online:0,presence:0,excused:0,unexcused:0};ATTENDANCE.records.forEach(r=>counts[r.status]++);return {...counts,total:ATTENDANCE.records.length,absent:counts.excused+counts.unexcused}}
function attendanceRequestStatus(r){if(!r.request)return t('Keine Meldung','No report');return t(...({open:['Meldung lokal vorgemerkt · Prüfung offen','Report noted locally · review pending'],clarify:['Zuordnung / Sachverhalt klären','Clarify assignment / circumstances'],corrected:['Musterkorrektur dokumentiert','Sample correction documented'],unchanged:['Musterprüfung beendet · Stand unverändert','Sample review finished · record unchanged']}[r.request.status]))}
function attendanceButton(de,en,act,disabled=false){return `<button type="button" class="btn secondary" data-att-action="${act}" ${disabled?'disabled':''}>${t(de,en)}</button>`}
function attendanceNotice(){return `<p class="learning-notice">${t('Lokale Anwesenheitssimulation · nur eine fiktive Person und zwei Mustereinheiten. Keine echten Teilnehmerdaten, Meldungen oder Leistungsfolgen. Kein QR- oder Meeting-Zugriff. Neuladen verwirft den Stand.','Local attendance simulation · one fictional learner and two sample lessons only. No real learner records, reports or academic consequences. No QR or meeting access. Reloading discards the state.')}</p>`}
function attendanceError(){return `<p id="attendance-error" role="alert" tabindex="-1">${ATTENDANCE.error&&ATTENDANCE.errorRoute===route()?esc(t(...ATTENDANCE.error)):''}</p>`}
function attendanceHistory(r){return `<details><summary>${t('Änderungsverlauf dieser Einheit','Change history for this lesson')}</summary><ol>${r.history.map(h=>`<li><b>${esc(h.at)} · ${t(...h.actor)}</b><p>${t(...h.action)}</p>${h.from?`<p>${t(...ATT_LABELS[h.from])} → ${t(...ATT_LABELS[h.to])}</p>`:''}<p class="learning-preserve">${esc(h.reason)}</p></li>`).join('')||`<li>${t('Fiktiver Ausgangsstand · noch keine lokalen Änderungen.','Fictional initial record · no local changes yet.')}</li>`}</ol></details>`}
function attendanceSummary(){const n=attendanceCounts();return `<section class="learning-panel"><h2>${t('Überblick der zwei Mustereinheiten','Overview of the two sample lessons')}</h2><dl class="attendance-counts">${Object.entries(ATT_LABELS).map(([k,labels])=>`<div><dt>${t(...labels)}</dt><dd>${n[k]}</dd></div>`).join('')}<div><dt>${t('Fehlzeiten insgesamt','Total absences')}</dt><dd>${n.absent} / ${n.total}</dd></div></dl><p>${t('Gezählt werden Mustereinheiten, keine verbindliche Anwesenheitsquote. Entschuldigte Fehlzeiten bleiben enthalten. Keine automatische Warnung oder Entscheidung.','Counts refer to sample lessons, not an official attendance percentage. Excused absences remain included. No automatic warning or decision.')}</p></section>`}
function attendanceList(){return `<nav class="attendance-records" aria-label="${t('Mustereinheiten','Sample lessons')}">${ATTENDANCE.records.map(r=>`<button type="button" class="attendance-record ${r.id===ATTENDANCE.selected?'selected':''}" data-att-select="${r.id}" aria-pressed="${r.id===ATTENDANCE.selected}"><strong>${esc(r.group)} · ${t(...r.subject)}</strong><span>${r.date} · ${r.time}</span><span>${t(...ATT_LABELS[r.status])}</span><small>${attendanceRequestStatus(r)}</small></button>`).join('')}</nav>`}
function attendanceContext(r){return `<dl class="learning-facts"><div><dt>${t('Betroffene Unterrichtseinheit','Affected lesson')}</dt><dd>${r.date} · ${r.time} · ${r.id}</dd></div><div><dt>${t('Tatsächlich besuchte Gruppe','Actual class attended')}</dt><dd>${r.group} · ${t(...r.subject)}</dd></div><div><dt>${t('Stammgruppe · Muster','Home class · sample')}</dt><dd>T-01</dd></div><div><dt>${t('Aktueller Musterstand','Current sample record')}</dt><dd id="attendance-current">${t(...ATT_LABELS[r.status])}</dd></div></dl><p>${t('Zuständig: Musterlehrkraft der tatsächlich besuchten Gruppe. Es liegen keine technischen Beitrittsdaten vor. Ein Online-Klick wäre allein kein Anwesenheitsnachweis.','Responsible: sample teacher of the actual class attended. No technical join data is available. An online click alone would not prove attendance.')}</p>`}
function attendanceStudent(){const r=attendanceRecord();if(!r)return notFound();const pending=r.request&&['open','clarify'].includes(r.request.status);return learningShell('student',`<div class="attendance-journey"><h1 id="attendance-heading" tabindex="-1">${t('Deine Anwesenheit nachvollziehen.','Understand your attendance record.')}</h1>${attendanceNotice()}${attendanceSummary()}${attendanceList()}<section class="learning-panel"><h2>${t('Einheit prüfen und Abweichung melden','Review a lesson and report a discrepancy')}</h2>${attendanceContext(r)}<p class="learning-status">${attendanceRequestStatus(r)}</p>${r.request?`<h3>${t('Deine lokale Meldung','Your local report')}</h3><p class="learning-preserve">${esc(r.request.message)}</p>${r.request.reply?`<h3>${t('Lokale Prüfrückmeldung','Local review response')}</h3><p class="learning-preserve">${esc(r.request.reply)}</p>`:''}`:''}<label class="field">${t('Fiktive Abweichung zur gewählten Einheit','Fictional discrepancy for the selected lesson')}<textarea id="attendance-report" maxlength="1500" ${pending?'disabled':''}>${esc(r.reportDraft)}</textarea></label><p>${t('Nur eine sachliche Beispielbeschreibung. Keine Gesundheitsdaten oder echten Nachweise eingeben. Die Meldung ändert den Anwesenheitsstand nicht. Antwortweg und Bearbeitungsfrist sind fachlich noch festzulegen.','Use a factual sample description only. Do not enter health data or actual evidence. Reporting does not change attendance. The response process and handling time still require specification.')}</p>${attendanceError()}${attendanceButton('Abweichung lokal vormerken','Note discrepancy locally','report',pending)}${attendanceHistory(r)}</section><div class="actions">${link(t('Lehrkräfteprüfung · Demo','Teacher review · demo'),'/portal/teacher/attendance','secondary')}</div></div>`)}
function attendanceTeacher(classbook=false){const r=attendanceRecord();if(!r)return notFound();const pending=r.request&&['open','clarify'].includes(r.request.status);const content=classbook?`<section class="learning-panel"><h2>${t('Anwesenheitsauszug · Klassenbuch','Attendance extract · classbook')}</h2>${ATTENDANCE.records.map(x=>`<article class="attendance-extract"><h3>${x.group} · ${t(...x.subject)}</h3><p>${x.date} · ${x.time}</p><p>${t(...ATT_LABELS[x.status])} · ${attendanceRequestStatus(x)}</p>${attendanceHistory(x)}</article>`).join('')}<p>${t('Nur Anwesenheitsauszug. Unterrichtsinhalte, Material- und Klassenbucheinträge sind damit nicht vollständig umgesetzt.','Attendance extract only. Lesson content, materials and full classbook records are not implemented by this view.')}</p></section>`:`${attendanceList()}<section class="learning-panel"><h2>${t('Meldung im Kurskontext prüfen','Review report in its class context')}</h2>${attendanceContext(r)}<p class="learning-status">${attendanceRequestStatus(r)}</p>${r.request?`<h3>${t('Gemeldete Abweichung · Muster','Reported discrepancy · sample')}</h3><p class="learning-preserve">${esc(r.request.message)}</p>`:`<p class="learning-empty">${t('Keine lokale Abweichungsmeldung für diese Einheit.','No local discrepancy report for this lesson.')}</p>`}${pending?`<label class="field">${t('Prüfnotiz / Rückmeldung · nur fiktiv','Review note / response · fictional only')}<textarea id="attendance-review" maxlength="1500">${esc(r.reviewDraft)}</textarea></label><label class="attendance-check"><input type="checkbox" id="attendance-checked" ${r.checked?'checked':''}>${t('Einheit, tatsächliche Gruppe und Sachverhalt im Muster geprüft','Lesson, actual class and circumstances reviewed in sample')}</label><label class="field">${t('Korrigierter Musterstatus','Corrected sample status')}<select id="attendance-proposed">${Object.entries(ATT_LABELS).map(([k,labels])=>`<option value="${k}" ${r.proposed===k?'selected':''}>${t(...labels)}</option>`).join('')}</select></label>${attendanceError()}<div class="actions">${attendanceButton('Musterkorrektur dokumentieren','Document sample correction','correct')}${attendanceButton('Stand unverändert bestätigen','Keep existing record','keep')}${attendanceButton('Klärbedarf vormerken','Mark clarification needed','clarify')}</div><p>${t('Bei unklarer Gruppenzuordnung zuerst Klärbedarf vormerken. Kein Zugriff auf andere Kurse und keine automatische Übernahme aus technischen Signalen.','If class assignment is unclear, mark clarification needed first. No access to other courses or automatic acceptance of technical signals.')}</p>`:''}${attendanceHistory(r)}</section>`;
return learningShell('teacher',`<div class="attendance-journey"><h1 id="attendance-heading" tabindex="-1">${classbook?t('Gültigen Musterstand nachvollziehen.','Follow the current sample record.'):t('Anwesenheitsmeldungen prüfen.','Review attendance reports.')}</h1>${attendanceNotice()}${attendanceSummary()}${content}<div class="actions">${link(t('Teilnehmeransicht · Demo','Learner view · demo'),'/portal/student/attendance','secondary')}${link(t('Anwesenheitsprüfung','Attendance review'),'/portal/teacher/attendance','secondary')}${link(t('Klassenbuchauszug','Classbook extract'),'/portal/teacher/classbook','secondary')}</div><p class="learning-source">WF-W11-02-01/-02 · W2G §11.2–11.3 · ${t('Meldestatus und Antwortweg als lokale UI-Ausgestaltung; keine Fachfreigabe.','Report states and response path are local UI design, not approved business rules.')}</p></div>`)}
function attendanceAction(act){const r=attendanceRecord();if(!r)return;ATTENDANCE.error=null;const fail=(de,en)=>{ATTENDANCE.error=[de,en];ATTENDANCE.errorRoute=route();render();document.getElementById('attendance-error')?.focus()};const record=(actor,action,reason,from,to)=>r.history.push({at:new Date().toISOString(),actor,action,reason,from,to});
 if(act==='report'&&attendanceOwnRoute()){if(r.request&&['open','clarify'].includes(r.request.status))return;if(!r.reportDraft.trim())return fail('Bitte eine fiktive Abweichung beschreiben.','Please describe a fictional discrepancy.');r.request={message:r.reportDraft.trim(),status:'open',reply:''};r.checked=false;r.reviewDraft='';r.proposed=r.status;record(['Musterteilnehmer','Sample learner'],['Abweichung lokal vorgemerkt · Stand unverändert.','Discrepancy noted locally · record unchanged.'],r.request.message);
 }else if(['correct','keep','clarify'].includes(act)&&attendanceTeacherRoute()&&r.request&&['open','clarify'].includes(r.request.status)){if(!r.reviewDraft.trim())return fail('Bitte eine fiktive Prüfbegründung ergänzen.','Please add a fictional review reason.');if(act!=='clarify'&&!r.checked)return fail('Einheit, Gruppe und Sachverhalt zuerst im Muster prüfen.','Review the lesson, class and circumstances in the sample first.');if(act==='correct'&&!Object.hasOwn(ATT_LABELS,r.proposed))return fail('Einen gültigen Musterstatus wählen.','Choose a valid sample status.');if(act==='correct'&&r.proposed===r.status)return fail('Der gewählte Status ist unverändert. Nutze „Stand unverändert bestätigen“.','The selected status is unchanged. Use “Keep existing record”.');const old=r.status;if(act==='correct')r.status=r.proposed;r.request.status=act==='correct'?'corrected':act==='keep'?'unchanged':'clarify';r.request.reply=r.reviewDraft.trim();record(['Musterlehrkraft · '+r.group,'Sample teacher · '+r.group],act==='correct'?['Musterkorrektur dokumentiert.','Sample correction documented.']:act==='keep'?['Bestehenden Musterstand nach Prüfung erhalten.','Existing sample record retained after review.']:['Klärbedarf dokumentiert · Stand unverändert.','Clarification needed · record unchanged.'],r.request.reply,old,r.status);r.checked=false;
 }else return;render();document.getElementById('attendance-heading')?.focus()}
const attendanceBodyBefore=v3Body;v3Body=function(r){if(r==='/portal/student/attendance')return attendanceStudent();if(r==='/portal/teacher/attendance')return attendanceTeacher();if(r==='/portal/teacher/classbook')return attendanceTeacher(true);return attendanceBodyBefore(r)};
const attendancePortalBefore=portalContent;portalContent=function(role,view){const body=attendancePortalBefore(role,view);return body+(role==='student'&&view==='overview'?`<section class="learning-panel"><h2>${t('Deine Anwesenheit','Your attendance')}</h2><p>${t('Eigene Mustereinheiten ansehen und Abweichungen lokal vormerken.','View your own sample lessons and note discrepancies locally.')}</p>${link(t('Anwesenheit öffnen','Open attendance'),'/portal/student/attendance','secondary')}</section>`:'')};
const attendanceNavBefore=learningShell;learningShell=function(role,body){let html=attendanceNavBefore(role,body);if(role==='student')html=html.replace('</nav>',`<a href="#/portal/student/attendance">${t('Meine Anwesenheit','My attendance')}</a></nav>`);if(role==='teacher')html=html.replace('</nav>',`<a href="#/portal/teacher/classbook">${t('Klassenbuchauszug','Classbook extract')}</a></nav>`);return html};
const attendancePortalNavBefore=portal;portal=function(role,view){let html=attendancePortalNavBefore(role,view);if(role==='student')html=html.replace('</nav>',`<a href="#/portal/student/attendance">${t('Meine Anwesenheit','My attendance')}</a></nav>`);return html};
const attendanceGuidanceBefore=v3Guidance;v3Guidance=function(a){if(route()==='/portal/student/attendance')return [t('Deine Einträge verstehen.','Understand your records.'),t('Eine Meldung ändert keinen Eintrag. Die zuständige Lehrkraft prüft den konkreten Fall.','A report does not change a record. The responsible teacher reviews the specific case.'),[['Meine Anwesenheit','My attendance','/portal/student/attendance'],['Mein Weg','My journey','/portal/student']]];if(['/portal/teacher/attendance','/portal/teacher/classbook'].includes(route()))return [t('Prüfen und nachvollziehbar korrigieren.','Review and document corrections.'),t('Tatsächliche Gruppe, Einheit und Begründung bleiben zusammen.','Keep the actual class, lesson and reason together.'),[['Anwesenheitsprüfung','Attendance review','/portal/teacher/attendance'],['Klassenbuchauszug','Classbook extract','/portal/teacher/classbook']]];return attendanceGuidanceBefore(a)};
const attendanceBindBefore=v3Bind;v3Bind=function(){attendanceBindBefore();document.querySelectorAll('[data-att-action]').forEach(el=>el.addEventListener('click',()=>attendanceAction(el.dataset.attAction)));document.querySelectorAll('[data-att-select]').forEach(el=>el.addEventListener('click',()=>{if(!ATTENDANCE.records.some(r=>r.id===el.dataset.attSelect))return;ATTENDANCE.selected=el.dataset.attSelect;ATTENDANCE.error=null;render();document.getElementById('attendance-heading')?.focus()}));for(const [id,key]of [['attendance-report','reportDraft'],['attendance-review','reviewDraft'],['attendance-proposed','proposed'],['attendance-checked','checked']])document.getElementById(id)?.addEventListener(id==='attendance-proposed'||id==='attendance-checked'?'change':'input',e=>{const r=attendanceRecord();if(r)r[key]=id==='attendance-checked'?e.target.checked:e.target.value})};
render();
